// Stats holds the request counters of a server.
type Stats struct {
	// Requests is the number of requests tried, retries included.
	Requests uint64 `json:"requests" msgpack:"requests"`
	// Retries is the number of requests tried again after a temporary error.
	Retries uint64 `json:"retries" msgpack:"retries"`
	// Timeouts is the number of requests that the unit did not answer in time.
	Timeouts uint64 `json:"timeouts" msgpack:"timeouts"`
	// Exceptions is the number of requests answered with an exception.
	Exceptions uint64 `json:"exceptions" msgpack:"exceptions"`
	// LastResponse is the time from sending the last answered request to its reply.
	LastResponse telem.TimeSpan `json:"last_response" msgpack:"last_response"`
	// MaxResponse is the longest time from sending a request to its reply.
	MaxResponse telem.TimeSpan `json:"max_response" msgpack:"max_response"`
}

// StatusDetails identifies the server and rack that a status pertains to.
type StatusDetails struct {
	// Rack is the key of the rack the server belongs to.
	Rack rack.Key `json:"rack" msgpack:"rack"`
	// Server is the key of the server.
	Server Key `json:"server" msgpack:"server"`
	// Connected is true when the server answered the last probe.
	Connected bool `json:"connected" msgpack:"connected"`
	// Stats holds the request counters. Absent until the first scan counts them.
	Stats *Stats `json:"stats,omitzero" msgpack:"stats,omitempty"`
}

// Status is the connection status of a server.
type Status = status.Status[StatusDetails]

// Server is a Modbus server that a rack's Driver connects to.
type Server struct {
	// Key uniquely identifies the server.
	Key Key `json:"key" msgpack:"key"`
	// Rack is the key of the rack whose Driver connects to the server.
	Rack rack.Key `json:"rack" msgpack:"rack"`
	// Name is a human-readable name for the server.
	Name string `json:"name" msgpack:"name"`
	// Connection holds the settings that the Driver connects with.
	Connection Connection `json:"connection" msgpack:"connection"`
	// RequestPolicy limits and paces the requests that the Driver sends.
	RequestPolicy RequestPolicy `json:"request_policy" msgpack:"request_policy"`
	// Reads bind the values that read tasks read to their channels.
	Reads []Read `json:"reads" msgpack:"reads"`
	// Writes bind the values that write tasks write to their command channels.
	Writes []Write `json:"writes" msgpack:"writes"`
	// Status is the current connection status of the server.
	Status *Status `json:"status,omitzero" msgpack:"status,omitempty"`
}

// SetDefaults sets every field that has a schema default to that default.
func (s *Server) SetDefaults() {
	s.RequestPolicy.SetDefaults()
}

// UnmarshalJSONFrom decodes the input over the value. A zero value first takes the
// schema defaults, so an omitted member takes its default and a zero stays.
func (s *Server) UnmarshalJSONFrom(dec *jsontext.Decoder) error {
	type plain Server
	if reflect.ValueOf(*s).IsZero() {
		s.SetDefaults()
	}
	return json.UnmarshalDecode(dec, (*plain)(s))
}

// DecodeMsgpack decodes the input over the value, as UnmarshalJSONFrom does.
func (s *Server) DecodeMsgpack(dec *vmsgpack.Decoder) error {
	type plain Server
	if reflect.ValueOf(*s).IsZero() {
		s.SetDefaults()
	}
	return dec.Decode((*plain)(s))
}

// Validate returns an error wrapping validate.ErrValidation if any field violates its
// schema constraints.
func (s Server) Validate() error {
	v := validate.New("Server")
	v.NotEmptyString("name", s.Name)
	v.Exec(func() error { return validate.PathedError(s.Connection.Validate(), "connection") })
	v.Exec(func() error { return validate.PathedError(s.RequestPolicy.Validate(), "request_policy") })
	for i := range s.Reads {
		v.Exec(func() error { return validate.PathedError(s.Reads[i].Validate(), "reads", strconv.Itoa(i)) })
	}
	for i := range s.Writes {
		v.Exec(func() error { return validate.PathedError(s.Writes[i].Validate(), "writes", strconv.Itoa(i)) })
	}
	return v.Error()
}
